INSERT INTO services (id, slug, name, category, tagline, description, benefits, duration_minutes, image, pickup_available, is_featured, sort_order, created_at, updated_at) VALUES (1, 'basic-exterior-wash', 'Basic Exterior Wash', 'Exterior', 'A quick, spotless rinse-and-dry for everyday shine.', 'Our express exterior wash removes road dust, grime and bird droppings using pH-neutral shampoo and a two-bucket method that protects your paint. Finished with a spot-free rinse and plush microfibre dry, it is the perfect weekly refresh for a daily driver.', '["pH-neutral shampoo, safe on all paints","Two-bucket wash to prevent swirl marks","Spot-free deionised water rinse","Microfibre hand dry and glass wipe"]', 45, '/assets/images/services/basic-exterior-wash.jpg', 1, 0, 1, TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -200 DAY), '09:00:00'), TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -200 DAY), '09:00:00'));
