INSERT INTO services (id, slug, name, category, tagline, description, benefits, duration_minutes, image, pickup_available, is_featured, sort_order, created_at, updated_at) VALUES (2, 'premium-wash', 'Premium Wash', 'Wash', 'Exterior and interior refresh with a gloss finish.', 'The Premium Wash combines a thorough exterior hand wash with an interior vacuum, dashboard wipe-down and glass polish. A spray sealant adds a glossy, water-beading layer that keeps your car cleaner for longer.', '["Full exterior hand wash and dry","Interior vacuum and dashboard detailing","Spray sealant for gloss and water beading","Tyre and trim dressing"]', 75, '/assets/images/services/premium-wash.jpg', 1, 1, 2, TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -200 DAY), '09:00:00'), TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -200 DAY), '09:00:00'));
