INSERT INTO services (id, slug, name, category, tagline, description, benefits, duration_minutes, image, pickup_available, is_featured, sort_order, created_at, updated_at) VALUES (3, 'interior-cleaning', 'Interior Deep Cleaning', 'Interior', 'Showroom-fresh cabin, seats to roof liner.', 'A complete cabin reset: deep vacuuming, steam cleaning of seats and carpets, stain treatment, AC vent cleaning and a germ-killing sanitisation. Ideal after long road trips, monsoon months or before selling your car.', '["Steam cleaning of seats and carpets","Stain and spill treatment","AC vent and console detailing","Anti-bacterial cabin sanitisation"]', 120, '/assets/images/services/interior-cleaning.jpg', 1, 0, 3, TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -200 DAY), '09:00:00'), TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -200 DAY), '09:00:00'));
