INSERT INTO services (id, slug, name, category, tagline, description, benefits, duration_minutes, image, pickup_available, is_featured, sort_order, created_at, updated_at) VALUES (4, 'foam-wash', 'Snow Foam Wash', 'Wash', 'Thick snow foam that lifts dirt before it touches paint.', 'A touch-less pre-wash with thick snow foam loosens and lifts dirt so it rinses away before any mitt touches your paint. Followed by a gentle contact wash, wheel cleaning and a streak-free dry - the safest wash for dark and premium paints.', '["Touch-less snow foam pre-wash","Minimises swirl marks and scratches","Wheel and arch cleaning","Streak-free blower and microfibre dry"]', 60, '/assets/images/services/foam-wash.jpg', 1, 1, 4, TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -200 DAY), '09:00:00'), TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -200 DAY), '09:00:00'));
