INSERT INTO services (id, slug, name, category, tagline, description, benefits, duration_minutes, image, pickup_available, is_featured, sort_order, created_at, updated_at) VALUES (5, 'ceramic-coating', 'Ceramic Coating', 'Protection', 'Years of hydrophobic, mirror-like paint protection.', 'A professional 9H nano-ceramic coating bonded to your paint after a full decontamination and one-step machine polish. It delivers deep gloss, strong UV and chemical resistance and a self-cleaning hydrophobic effect. Includes a 2-year warranty card.', '["9H nano-ceramic layer with 2-year warranty","Paint decontamination and machine polish","UV, bird-dropping and chemical resistance","Extreme water beading and easy cleaning"]', 480, '/assets/images/services/ceramic-coating.jpg', 0, 1, 5, TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -200 DAY), '09:00:00'), TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -200 DAY), '09:00:00'));
