INSERT INTO services (id, slug, name, category, tagline, description, benefits, duration_minutes, image, pickup_available, is_featured, sort_order, created_at, updated_at) VALUES (6, 'wax-polishing', 'Wax Polishing', 'Paint care', 'Hand-applied carnauba wax for a warm, deep glow.', 'After a careful wash and clay-bar treatment, premium carnauba wax is applied by hand and buffed to a deep, warm glow. Wax hides light swirls, adds protection for up to three months and makes every colour look richer.', '["Clay-bar paint decontamination","Premium carnauba hand wax","Hides light swirls and dullness","Up to 3 months of protection"]', 150, '/assets/images/services/wax-polishing.jpg', 1, 0, 6, TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -200 DAY), '09:00:00'), TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -200 DAY), '09:00:00'));
