INSERT INTO services (id, slug, name, category, tagline, description, benefits, duration_minutes, image, pickup_available, is_featured, sort_order, created_at, updated_at) VALUES (7, 'engine-cleaning', 'Engine Bay Cleaning', 'Engine', 'Safe degreasing for a clean, healthy engine bay.', 'Electrical parts are covered, then a safe water-based degreaser and soft brushes remove oil, dust and grime from the engine bay. Plastics and hoses are dressed with a protectant so the bay looks new and leaks are easier to spot.', '["Sensitive electrics protected first","Water-based, non-corrosive degreaser","Hose and plastic protectant dressing","Easier to spot leaks early"]', 60, '/assets/images/services/engine-cleaning.jpg', 1, 0, 7, TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -200 DAY), '09:00:00'), TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -200 DAY), '09:00:00'));
