INSERT INTO products (id, sku, slug, name, category_id, brand, description, features, specs, images, price_paise, mrp_paise, stock, is_universal, fitment_available, warranty, is_active, is_featured, is_deal, created_at, updated_at) VALUES (1, 'CZ-INT-001', 'premium-leatherette-seat-covers-black-tan', 'Premium Leatherette Seat Covers (Black-Tan)', 1, 'CarZone Pro', 'Tailor-made seat covers that protect your original upholstery from spills, sweat and wear while giving the cabin a premium, showroom-new look. Premium Leatherette Seat Covers (Black-Tan) by CarZone Pro. Designed for a precise fit on the listed models.', '["Material: PU leatherette","Seats covered: 5 seats + headrests","Easy installation - or book fitment at a CarZone centre","1 year warranty"]', '{"Material":"PU leatherette","Seats covered":"5 seats + headrests","Colour":"Black with tan inserts","Brand":"CarZone Pro","Warranty":"1 year"}', '["/assets/images/products/premium-leatherette-seat-covers-black-tan-1.jpg","/assets/images/products/premium-leatherette-seat-covers-black-tan-2.jpg"]', 649900, 999900, 39, 0, 1, '1 year', 1, 1, 0, TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -60 DAY), '09:00:00'), TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -60 DAY), '09:00:00'));
INSERT INTO products (id, sku, slug, name, category_id, brand, description, features, specs, images, price_paise, mrp_paise, stock, is_universal, fitment_available, warranty, is_active, is_featured, is_deal, created_at, updated_at) VALUES (2, 'CZ-INT-002', '3d-luxury-floor-mats', '3D Luxury Floor Mats', 1, 'AutoNova', 'Precision-cut mats with raised edges that trap mud, water and dust, keeping the floor of your car spotless in every season. 3D Luxury Floor Mats by AutoNova. Designed for a precise fit on the listed models.', '["Material: TPE rubber","Pieces: 5","Easy installation","6 months warranty"]', '{"Material":"TPE rubber","Pieces":"5","Edge height":"3 cm","Brand":"AutoNova","Warranty":"6 months"}', '["/assets/images/products/3d-luxury-floor-mats-1.jpg","/assets/images/products/3d-luxury-floor-mats-2.jpg"]', 299900, 499900, 35, 0, 0, '6 months', 1, 0, 1, TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -59 DAY), '09:00:00'), TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -59 DAY), '09:00:00'));
